<?php require_once __DIR__.'/../includes/bootstrap.php';$code=trim($_GET['code']??'');$cert=null;if($code){$q=db()->prepare('SELECT c.type,c.certificate_no,c.issue_date,c.status,u.name,v.id verification_id FROM certificates c JOIN students s ON s.id=c.student_id JOIN users u ON u.id=s.user_id JOIN certificate_verifications v ON v.certificate_id=c.id WHERE v.verification_code=? LIMIT 1');$q->execute([$code]);$cert=$q->fetch();if($cert){db()->prepare('UPDATE certificate_verifications SET verified_count=verified_count+1,last_verified_at=NOW() WHERE id=?')->execute([$cert['verification_id']]);}}
?><!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><link rel='stylesheet' href='../assets/css/app.css'><title>Certificate Verification</title></head><body class='login-bg'><div class='login-card'><div class='brand big'>DCOS <span>2077</span></div><h2>Official Document Verification</h2><form><input class='form-control' name='code' value='<?=e($code)?>' placeholder='Verification code' required><button class='btn btn-primary mt-3 w-100'>Verify</button></form><?php if($code):?><div class='alert alert-<?=($cert&&$cert['status']==='Issued'?'success':'danger')?> mt-4'><?php if($cert):?><strong>Certificate Valid</strong><br>Type: <?=e($cert['type'])?><br>Issued To: <?=e($cert['name'])?><br>Certificate No: <?=e($cert['certificate_no'])?><br>Issue Date: <?=e($cert['issue_date'])?><br>Status: <?=e($cert['status'])?><?php else:?>No matching certificate found.<?php endif;?></div><?php endif;?></div></body></html>
